-- G1b 设备指纹(2026-10-31,goal-b39 对齐 Qoder 0.5.1 设备互联安全面)。
-- devices.fingerprint:客户端自生成并持久存的绑定凭据;注册(兑换)时写入,
-- 此后设备请求头部 X-Device-Fingerprint 必须与绑定值一致,否则 403。
-- nullable:存量设备行(以及未声明指纹的新客户端)不绑定,校验自动跳过,
-- 逐字节保持旧行为;绑定后才开始生效。
ALTER TABLE "devices" ADD COLUMN "fingerprint" varchar(128);
